/*
 * prog24_query_string_parser – reproduced behavior
 *
 * The original binary reads a single line from standard input,
 * interprets it as a URL‑encoded query string (the part after the
 * '?' in an HTTP GET request) and prints each key/value pair on its
 * own line in the form:
 *
 *     key=value
 *
 * If no line can be read (e.g. EOF on stdin) the program prints
 * the literal string "NO_INPUT" and exits.
 *
 * The parsing rules are:
 *   • Pairs are separated by '&'.
 *   • Within a pair the first '=' separates the key from the value.
 *   • Both key and value are URL‑decoded:
 *        – '+' is translated to a space character.
 *        – "%XY" where X and Y are hexadecimal digits is replaced by the
 *          byte with value 0xXY.
 *        – Any other character is copied unchanged.
 *   • If a pair contains no '=', the value is considered empty.
 *
 * The implementation below follows these rules using straightforward
 * C code; it does not attempt to reproduce the original obfuscated
 * control flow, only the observable output.
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <ctype.h>

#define MAX_LINE 2048   /* matches the 0x800 buffer used in the binary */

/* ------------------------------------------------------------------ */
/* URL‑decode a string.
 *
 *  src   – pointer to the input string (may contain %XX escapes and '+')
 *  dst   – buffer where the decoded string will be written; must be large
 *          enough to hold the result (the same size as src is sufficient).
 *
 * The function returns the number of bytes written (excluding the final
 * NUL terminator).  It always NUL‑terminates the output.
 */
static size_t url_decode(const char *src, char *dst)
{
    size_t out = 0;
    while (*src) {
        if (*src == '+') {
            dst[out++] = ' ';
            src++;
        } else if (*src == '%' && isxdigit((unsigned char)src[1]) && isxdigit((unsigned char)src[2])) {
            char hex[3] = { src[1], src[2], 0 };
            dst[out++] = (char)strtoul(hex, NULL, 16);
            src += 3;
        } else {
            dst[out++] = *src++;
        }
    }
    dst[out] = '\0';
    return out;
}

/* ------------------------------------------------------------------ */
int main(void)
{
    char line[MAX_LINE];

    /* Read a line from stdin.  The original program used fgets with a
       buffer size of 0x800 (2048) bytes. */
    if (fgets(line, sizeof(line), stdin) == NULL) {
        puts("NO_INPUT");
        return 0;
    }

    /* Strip trailing newline and carriage‑return characters that may be
       present because the original state machine explicitly handled them. */
    size_t len = strlen(line);
    while (len > 0 && (line[len - 1] == '\n' || line[len - 1] == '\r')) {
        line[--len] = '\0';
    }

    /* Parse the query string.  Pairs are separated by '&'. */
    char *pair = line;
    while (pair && *pair) {
        char *next_pair = strchr(pair, '&');
        if (next_pair) {
            *next_pair = '\0';          /* temporarily terminate this pair */
            next_pair++;               /* start of the following pair */
        }

        /* Split the pair into key and value at the first '=' */
        char *eq = strchr(pair, '=');
        char *key_part;
        char *val_part;
        if (eq) {
            *eq = '\0';
            key_part = pair;
            val_part = eq + 1;
        } else {
            key_part = pair;
            val_part = "";             /* empty value if no '=' */
        }

        /* Decode key and value */
        char key_decoded[MAX_LINE];
        char val_decoded[MAX_LINE];
        url_decode(key_part, key_decoded);
        url_decode(val_part, val_decoded);

        /* Output the result */
        printf("%s=%s\n", key_decoded, val_decoded);

        /* Move to the next pair */
        pair = next_pair;
    }

    return 0;
}
